const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6h14M5 18h14"/>',book:'<path d="M4 4h6a3 3 0 0 1 2 1 3 3 0 0 1 2-1h6v15h-6a3 3 0 0 0-2 1 3 3 0 0 0-2-1H4zM12 5v15"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6z"/>',file:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h5"/>',layers:'<path d="m12 3 10 6-10 6L2 9zM2 13l10 6 10-6M2 17l10 6 10-6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M17 14a5 5 0 0 1 4 5v2"/>',chart:'<path d="M4 3v17h17M8 15v-4M13 15V7M18 15V4"/>',city:'<path d="M3 21V8h7v13M10 21V3h11v18M6 11v1m0 3v1M14 7h3m-3 4h3m-3 4h3M1 21h22"/>',trade:'<path d="M3 7h16l-4-4M21 17H5l4 4M19 7l-4 4M5 17l4-4"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-1 1-2 1-2 3M12 17h.01"/>',bulb:'<path d="M9 18h6M9 21h6M8 14a7 7 0 1 1 8 0l-1 2H9z"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
const ic=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const KEY='nation-lab-v1';const blank=()=>({round:0,stage:0,entries:[],draft:{choice:null,prediction:null,confidence:60,support:'skills',hypothesis:''}});
let state={country:'KOR',cases:{KOR:blank(),ARG:blank(),SGP:blank()}};let storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&CASES.some(c=>c.id===saved.country)&&CASES.every(c=>saved.cases?.[c.id]&&Number.isInteger(saved.cases[c.id].round)&&saved.cases[c.id].round>=0&&saved.cases[c.id].round<=2&&Number.isInteger(saved.cases[c.id].stage)&&saved.cases[c.id].stage>=0&&saved.cases[c.id].stage<=4&&Array.isArray(saved.cases[c.id].entries)&&saved.cases[c.id].draft))state=saved}catch(e){storageOK=false}
const c=()=>CASES.find(x=>x.id===state.country),session=()=>state.cases[state.country],r=()=>c().rounds[session().round],year=()=>c().start+session().round*10;
const values=(yr=year())=>EVIDENCE[c().id][String(yr)];
const growth=()=>((values(year()+10)['NY.GDP.PCAP.KD']/values()['NY.GDP.PCAP.KD']-1)*100);
const predictLabels=['下降','增长不足 30%','增长 30%–80%','增长超过 80%'];
const supportLabels={skills:'教育与技能',infrastructure:'基础设施',buffer:'财政与外汇缓冲'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false}}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2400)}
function total(){return Object.values(state.cases).reduce((n,s)=>n+s.entries.filter(Boolean).length,0)}
function shell(content){return `<aside class="sidebar"><div class="brand"><div class="brand-mark">${ic('globe')}</div><div><div class="brand-title">国运</div><div class="brand-sub">国家发展实验室</div></div></div><div class="nav-label">探索与思考</div><button class="nav-item active" data-action="home" title="历史实验">${ic('compass')}<span>历史实验</span></button><button class="nav-item" data-action="countries" title="国家档案">${ic('globe')}<span>国家档案</span><span class="count">3</span></button><button class="nav-item" data-action="notebook" title="我的判断">${ic('book')}<span>我的判断</span><span class="count">${total()}</span></button><div class="nav-label">理解这个实验</div><button class="nav-item" data-action="method" title="方法与边界">${ic('layers')}<span>方法与边界</span></button><button class="nav-item" data-action="sources" title="数据与来源">${ic('file')}<span>数据与来源</span></button><div class="sidebar-foot"><strong>历史没有标准答案。</strong>在当时的信息里作出判断，<br>在真实的历史中修正直觉。<div class="round-dots">${[0,1,2].map(i=>`<i class="${session().entries[i]?'on':''}"></i>`).join('')}<span>${session().entries.filter(Boolean).length} / 3 轮已下注</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><span class="mobile-brand">国运</span><span>历史实验</span>${ic('chevron')}<b>${c().name}档案</b></div><button class="top-note" data-action="notebook" title="查看已保存的判断">${ic('book')}${storageOK?'判断自动保存在本机':'本机存储不可用，请导出判断'}</button></header><div class="workspace"><div class="page-head"><div><h1>${session().stage===4?'把经验带到下一个国家':'站在历史的岔路口'}</h1><p class="subtitle">${session().stage===4?'留下更好的问题，比记住一个答案更重要。':'先做出你的判断，再打开这十年的历史。'}</p></div><button class="btn" data-action="countries">${ic('globe')}切换国家</button></div>${session().stage<4?steps():''}${content}<footer class="footer"><span>国运 · 一个关于约束、选择与不确定性的实验</span><button class="text-btn" data-action="method">方法与边界</button></footer></div></main>`}
function steps(){return `<nav class="steps" aria-label="实验进度">${['观察条件','判断与下注','揭示历史','比较与归因'].map((t,i)=>`<div class="step ${i===session().stage?'current':i<session().stage?'done':''}" ${i===session().stage?'aria-current="step"':''}><span class="step-num">${i<session().stage?'✓':String(i+1).padStart(2,'0')}</span><span>${t}</span>${i<3?'<i class="step-line"></i>':''}</div>`).join('')}</nav>`}
function footer(left,buttons){return `<div class="bottom-bar"><div class="bottom-hint">${ic('lock')}<span>${left}</span></div><div style="display:flex;gap:10px">${buttons}</div></div>`}
function metric(icon,label,value,unit,sub){return `<div class="metric"><div class="metric-label">${ic(icon)}${label}</div><div class="metric-number">${value}<span>${unit}</span></div><div class="metric-sub">${sub}</div></div>`}
function observe(){let v=values();return `<section class="overview"><div class="atlas"><div class="atlas-grid"></div><img src="${c().id}.svg" alt="${c().name}地理轮廓（现代边界，仅用于定位）"><div class="atlas-top"><span class="archive-tag">历史档案 ${String(CASES.indexOf(c())+1).padStart(2,'0')}</span><span>第 ${session().round+1} / 3 轮</span></div><h2>${c().name}</h2><div class="english">${c().en}</div><div class="year">${year()}<span>年 · 决策时点</span></div><div class="atlas-bottom"><span>${c().region}</span><span>${c().coordinates}</span></div></div><div class="metrics">${metric('people','总人口',(v['SP.POP.TOTL']/10000).toLocaleString('zh-CN',{maximumFractionDigits:0}),'万','劳动力，也是需要供养的人口')}${metric('chart','人均 GDP',Math.round(v['NY.GDP.PCAP.CD']).toLocaleString(),'美元','当年现价美元 · 不用于计算实际增长')}${metric('city','城市化率',v['SP.URB.TOTL.IN.ZS'].toFixed(1),'%','城市人口占总人口的比例')}${metric('trade','出口 / GDP',v['NE.EXP.GNFS.ZS'].toFixed(1),'%',c().id==='SGP'?'含转口贸易，比例可超过 100%':'商品与服务出口占 GDP 的比例')}</div></section><div class="source-line"><span>数据：世界银行 WDI，${year()} 年；历史修订值，按展示精度取整。</span><button class="text-btn" data-action="sources">查看口径与来源</button></div><div class="section-head"><h2>此刻，真正重要的约束</h2><button class="text-btn" data-action="context">展开完整背景</button></div><section class="observe-bottom"><div class="constraint-list">${r().constraints.map((x,i)=>`<article class="constraint"><div class="constraint-icon">${ic(['trade','people','layers'][i])}</div><div><h3>${x[0]}</h3><p>${x[1]}</p></div></article>`).join('')}</div><aside class="question-card"><div class="eyebrow">${ic('bulb')}把自己放在当时</div><h3>${r().title}</h3><p>${r().lead}</p><div class="tiny">你拥有当时的条件，还没有未来的答案。</div></aside></section>${footer(`${year()+10} 年的结果尚未揭示`,`<button class="btn primary" data-action="decide">开始判断</button>`)}`}
function decide(){let d=session().draft;return `<section class="narrative"><h2>${r().title}</h2><p>${r().lead}</p></section><div class="section-head"><h2>如果由你决策，先走哪条路？</h2><span>选择一条优先路线</span></div><div class="options" role="group" aria-label="优先政策路线">${r().options.map((o,i)=>`<button class="option ${d.choice===i?'selected':''}" data-choice="${i}" aria-pressed="${d.choice===i}"><div class="option-top"><span>${['A','B','C'][i]}</span><i class="radio"></i></div><h3>${o[0]}</h3><p>${o[1]}</p><div class="tradeoff">需要承担的代价<br>${o[2]}</div></button>`).join('')}</div><section class="form-panel"><label class="label">有限的配套资源，你会优先放在哪里？</label><div class="support-row" role="group" aria-label="配套政策">${Object.entries(supportLabels).map(([k,v])=>`<button class="pill ${d.support===k?'selected':''}" data-support="${k}" aria-pressed="${d.support===k}">${v}</button>`).join('')}</div><div class="form-grid"><div><label class="label">不管最终采取哪条路线，你预期这个国家十年后…</label><div class="choices" role="group" aria-label="实际人均 GDP 增长预测">${predictLabels.map((p,i)=>`<button class="pill ${d.prediction===i?'selected':''}" data-prediction="${i}" aria-pressed="${d.prediction===i}">${p}</button>`).join('')}</div><p class="help">预测的是历史实际人均 GDP 变化（固定价），不是你的政策会创造的虚构结果。</p></div><div><div class="confidence-label"><label class="label" for="confidence">你对这个增长区间有多大信心？</label><strong id="confidence-value">${d.confidence}%</strong></div><input id="confidence" type="range" min="10" max="100" step="5" value="${d.confidence}" aria-label="预测信心"><div class="range-labels"><span>保留很多疑问</span><span>非常确定</span></div><p class="help">下注的是你的判断。没有积分，也没有输赢。</p></div></div><div class="divider"></div><label class="label" for="hypothesis">写下你认为会起作用的因果链 <span class="muted">（选填）</span></label><textarea id="hypothesis" maxlength="1800" placeholder="我认为…会通过…改善…；如果…发生，我会修改判断。">${esc(d.hypothesis)}</textarea><p class="required-note" id="required-note">${d.choice===null||d.prediction===null?'选好政策路线和增长预期后，就可以封存判断。':'判断将被封存，随后揭示真实历史。'}</p></section>${footer('封存后保留原判断，方便诚实复盘',`<button class="btn" data-action="observe">返回观察</button><button class="btn primary" id="commit" data-action="commit" ${d.choice===null||d.prediction===null?'disabled':''}>封存判断，揭示历史</button>`)}`}
function chart(){const y=year(), rows=Array.from({length:11},(_,i)=>[y+i,EVIDENCE[c().id][String(y+i)]['NY.GDP.PCAP.KD']]);let base=rows[0][1], vs=rows.map(x=>x[1]/base*100), min=Math.floor(Math.min(...vs)*.85/20)*20,max=Math.ceil(Math.max(...vs)*1.1/20)*20;const px=i=>40+i*63,py=v=>155-(v-min)/(max-min)*125;let line=vs.map((v,i)=>`${i?'L':'M'}${px(i)},${py(v)}`).join(' ');return `<svg class="chart" viewBox="0 0 710 190" role="img" aria-label="${y} 至 ${y+10} 年实际人均 GDP 指数，从 100 变为 ${vs[10].toFixed(1)}">${[min,(min+max)/2,max].map(t=>`<path d="M40 ${py(t)}H670" stroke="#e4eaf0"/><text x="0" y="${py(t)+4}">${Math.round(t)}</text>`).join('')}<path d="${line} L670 155 L40 155Z" fill="#e8f0f7"/><path d="${line}" stroke="#527fa7" stroke-width="2.5" fill="none"/>${vs.map((v,i)=>`<circle cx="${px(i)}" cy="${py(v)}" r="3" fill="#527fa7"><title>${y+i}：${v.toFixed(1)}</title></circle>`).join('')}${[0,5,10].map(i=>`<text x="${px(i)}" y="182" text-anchor="middle">${y+i}</text>`).join('')}</svg>`}
function reveal(){const e=session().entries[session().round];return `<section class="reveal-top"><div class="history-card"><div class="tag">档案已开启 · ${year()}—${year()+10}</div><h2>真实历史走了哪条路？</h2><p>${r().actual}</p></div><div class="timeline">${r().events.map(ev=>`<div class="event"><b>${ev[0]}</b><span>${ev[1]}</span></div>`).join('')}</div></section><section class="growth-panel"><div class="growth-header"><div><h3>十年后，实际人均 GDP 的变化</h3><div class="help">固定 2015 年美元 · ${year()} 年 = 100</div></div><div class="growth-number">${growth()>0?'+':''}${growth().toFixed(1)}<span style="font-size:20px">%</span></div></div>${chart()}<div class="source-line"><span>世界银行 NY.GDP.PCAP.KD。折线包含衰退与波动，而不只看两个端点。</span><button class="text-btn" data-action="sources">数据来源</button></div></section><div class="comparison"><div><h3>你封存的路线</h3><strong>${r().options[e.choice][0]}</strong><p>优先配套：${supportLabels[e.support]}<br>增长预期：${predictLabels[e.prediction]}<br>当时信心：${e.confidence}%</p></div><div><h3>历史观察值与你的预期</h3><strong>${growthBucket()===e.prediction?'落在你预期的区间内':'落在你预期的区间外'}</strong><p>这只是一次判断的校准。预测吻合不意味着政策正确；预测偏离也不能证明你的路线会失败。</p></div></div><div class="notice">真实历史实行的是一组不断变化的政策。你的选择没有被套进虚构的经济模型，也不会生成“如果是你，GDP 就会是多少”的精确数字。</div>${footer('看见结果，只是理解的开始',`<button class="btn primary" data-action="explain">比较选择，拆解因果</button>`)}`}
function growthBucket(){let g=growth();return g<0?0:g<30?1:g<=80?2:3}
function explain(){const e=session().entries[session().round];return `<section class="narrative"><h2>发生在一起，不等于互为因果。</h2><p>回看 ${c().name}的 ${year()}—${year()+10} 年。把能力、选择与偶然分开，再想一遍你的判断。</p></section><div class="comparison" style="margin-top:0;margin-bottom:22px"><div><h3>你的原始假设</h3><strong style="font-size:16px">${r().options[e.choice][0]}</strong><p>${e.hypothesis?esc(e.hypothesis):'当时没有写下因果链。现在可以补上你认为最重要的机制。'}</p><p>配套优先：${supportLabels[e.support]}</p></div><div><h3>检查你的政策需要什么前提</h3><p style="margin-top:0">${r().options[e.choice][1]} 但需要面对：${r().options[e.choice][2]}</p><p>${{skills:'技能形成需要时间，也需要企业创造能使用这些技能的岗位。',infrastructure:'设施只有被有效使用才有产出；融资和维护同样构成约束。',buffer:'缓冲能降低危机暴露，但积累储备和收紧支出也有机会成本。'}[e.support]}</p></div></div><div class="cause-list">${['结构性因素','政策选择','外部环境','运气与时点','归因的不确定性'].map((label,i)=>`<article class="cause-row"><div class="cause-label"><span>${String(i+1).padStart(2,'0')}</span>${label}</div><p>${r().causes[i]}</p></article>`).join('')}</div><div class="cost"><strong>不要被增长数字遮住：</strong>${r().cost}</div><section class="form-panel"><label class="label" for="reflection">下一次，我会先问这个问题</label><p style="font-family:'Noto Serif SC',serif;font-size:20px;line-height:1.7;margin:14px 0 18px">${r().question}</p><textarea id="reflection" maxlength="1800" placeholder="哪一个前提被我低估了？什么证据会让我改变判断？">${esc(e.reflection||'')}</textarea><p class="help">保留原始判断，另写修正。空白也可以继续，但写下来更容易看见自己的变化。</p></section>${footer(session().round<2?'下一轮会从新的历史条件开始':'完成后回顾你的三轮判断',`<button class="btn" data-action="reveal">回看历史</button><button class="btn primary" data-action="next">${session().round<2?'进入 '+(year()+10)+' 年':'完成本国实验'}</button>`)}`}
function summary(){return `<section class="narrative"><h2>你已经穿过了 ${c().name}的三十年。</h2><p>带走的不是一条“发展公式”，而是辨认约束、检查机制、寻找反证的习惯。</p></section><div class="summary-grid">${session().entries.map((e,i)=>`<article class="summary-card"><h3>${c().start+i*10}—${c().start+(i+1)*10}</h3><p><b>${c().rounds[i].options[e.choice][0]}</b><br>预期：${predictLabels[e.prediction]}<br>当时信心：${e.confidence}%</p><div class="divider"></div><p>${e.reflection?esc(e.reflection):'这一轮尚未写下修正。可以在「我的判断」中回顾记录。'}</p></article>`).join('')}</div><div class="section-head"><h2>面对下一个陌生国家，先问什么？</h2></div><div class="takeaways">${[['约束','真正卡住发展的，是外汇、技能、财政，还是执行能力？'],['机制','这项政策通过什么环节起作用？谁有能力执行？'],['分配','收益归谁、成本由谁承担？这种分配能持续吗？'],['反证','哪种观察会推翻我的解释？增长有多少来自外部顺风？']].map(x=>`<div class="takeaway"><b>${x[0]}</b>${x[1]}</div>`).join('')}</div>${footer('你的原始判断与修正都已保留',`<button class="btn" data-action="export">${ic('download')}导出判断</button><button class="btn primary" data-action="countries">探索另一个国家</button>`)}`}
function render(scroll=true){$('#app').innerHTML=shell([observe,decide,reveal,explain,summary][session().stage]());if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function openModal(title,body){$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="关闭">${ic('close')}</button></div><div class="modal-body">${body}</div>`;$('#modal').showModal();document.body.classList.add('modal-open')}
function closeModal(){$('#modal').close();document.body.classList.remove('modal-open')}
function countries(){openModal('选择一个历史起点',`<p style="margin-top:0;margin-bottom:22px">三个国家，三组不同的约束。每个案例包含三轮；在封存判断之前，不展示未来结果。切换会保留当前进度。</p>${CASES.map(x=>`<button class="country-option" data-country="${x.id}"><span class="country-code">${x.id}</span><div><h3>${x.name} <span class="muted" style="font-size:13px;font-weight:400">${x.start} 年</span></h3><p>${x.intro}</p></div><span class="country-end">${state.cases[x.id].stage===4?'已完成':state.cases[x.id].entries.filter(Boolean).length?'继续实验':'打开档案'}</span></button>`).join('')}<p class="help">国家名称公开，未来路径按轮次解锁。若你已熟悉某国历史，可以选择较陌生的案例。</p>`)}
function context(){openModal(`${c().name} · ${year()} 年的背景`, `<div class="detail-item"><h3>地理与资源</h3><p>${c().geo}</p></div>${Object.entries(r().context).map(([k,v])=>`<div class="detail-item"><h3>${k}</h3><p>${v}</p></div>`).join('')}<div class="detail-item"><h3>产业结构补充</h3><p>农业、林业和渔业增加值占 GDP ${values()['NV.AGR.TOTL.ZS']?.toFixed(1)??'缺失'}%。这是产出占比，不是农业就业占比。</p></div><p class="help">背景仅覆盖该决策时点及以前。现代地图用于位置示意，不作为历史领土证据。</p>`)}
function method(){openModal('方法与边界',`<div class="detail-item"><h3>这是历史判断实验，不是计分游戏</h3><p>每轮先观察约束，选择优先路线与配套方向，预测实际增长区间并封存信心；随后打开真实历史，比较预期，拆解因果并记录修正。</p></div><div class="detail-item"><h3>你选的是优先次序，不是完整施政纲领</h3><p>现实中的政策往往重叠、调整且相互影响。这里把它们压缩为可讨论的选择，不代表只能实行一项政策。配套方向表示注意力与资源优先级，不是假定财政预算。</p></div><div class="detail-item"><h3>历史结果不是你的反事实结果</h3><p>系统不模拟你的路线会产生多少 GDP，也不把真实路径当作正确答案。政策比较用于发现前提和代价。观察性历史材料不能自动识别某项政策的净效应。</p></div><div class="detail-item"><h3>数据与“当时可知”的区别</h3><p>初始条件采用世界银行今天可获得的历史修订序列，表示对当时状态的回溯估计，不是假装重建当年的实时统计。每轮只展示截至该时点的状态；十年后的结果封存后才出现。</p></div><div class="detail-item"><h3>信心用于长期校准</h3><p>一次猜中或猜错不能说明判断能力。信心表示你认为真实增长落入所选区间的概率，需要多次独立判断才有校准意义。这里不产生排名或综合分数。</p></div><div class="detail-item"><h3>存档方式</h3><p>判断保存在当前浏览器的本地存储中，不会跨设备同步；清除浏览器数据会删除记录。可以导出文本留存。</p></div><button class="btn" data-action="export">导出当前记录</button>`)}
function sources(){const code=c().id;openModal('数据、史料与口径',`<p style="margin-top:0">数值来自世界银行 WDI API，读取于 2026-10-05；质性叙事依据下列参考文献综合编写，因果分析是带有边界的解释，而非文献结论的逐字引述。外部史料可能包含尚未解锁的历史。</p>${[['SP.POP.TOTL','总人口','人口数量，展示为万人。'],['NY.GDP.PCAP.CD','人均 GDP（现价美元）','用于描述当时收入水平，受汇率与价格影响，不用于实际增长计算。'],['SP.URB.TOTL.IN.ZS','城市人口占比','按各国城市定义统计，跨国比较存在口径差异。'],['NE.EXP.GNFS.ZS','商品与服务出口 / GDP','出口为总额，GDP 为增加值。新加坡的转口贸易使比例可超过 100%。'],['NY.GDP.PCAP.KD','实际人均 GDP（固定 2015 年美元）','十年变化 =（末年 / 初年 − 1）× 100%，不是年均增速；折线以初年 = 100。'],['NV.AGR.TOTL.ZS','农林渔业增加值占 GDP','只在背景资料中展示；不可当作就业占比。']].map(x=>`<div class="source-item"><h3>${x[1]}</h3><p>${x[2]}</p><a href="https://api.worldbank.org/v2/country/${code}/indicator/${x[0]}?format=json&date=${c().start}:${c().start+30}&per_page=100" target="_blank" rel="noopener noreferrer">世界银行原始序列 · ${x[0]}</a></div>`).join('')}<div class="source-item"><h3>韩国：产业政策与增长解释</h3><p>Alice H. Amsden, Asia’s Next Giant (1989)；World Bank, The East Asian Miracle (1993)。两者对政府干预的解释存在差异，适合对照阅读。KDI 的韩国经济发展史材料可补充政策时间线。</p><a href="https://documents1.worldbank.org/curated/en/975081468244550798/pdf/multi-page.pdf" target="_blank" rel="noopener noreferrer">世界银行报告原文</a></div><div class="source-item"><h3>阿根廷：稳定、债务与汇率制度</h3><p>Gerchunoff & Llach, El ciclo de la ilusión y el desencanto；IMF Independent Evaluation Office, The IMF and Argentina, 1991–2001 (2004)。后者是对 IMF 角色的独立评估，不能替代全部历史视角。</p><p>出版机构：IMF Independent Evaluation Office，2004 年。可按完整报告题名检索。</p></div><div class="source-item"><h3>新加坡：发展战略与政策调整</h3><p>W. G. Huff, The Economic Growth of Singapore (1994)；Economic Committee, The Singapore Economy: New Directions (1986)。经济发展局机构介绍可补充了解其职能；政策时间线参见上述历史著作与 1986 年报告。</p><a href="https://www.edb.gov.sg/en/about-edb/who-we-are.html" target="_blank" rel="noopener noreferrer">新加坡经济发展局机构介绍</a></div><div class="source-item"><h3>地图</h3><p>Natural Earth，经 datasets/geo-countries 获取的现代国界轮廓。用于定位，不重建历史边界。</p><a href="https://github.com/datasets/geo-countries" target="_blank" rel="noopener noreferrer">地图数据仓库</a></div>`)}
function notebook(){let all=CASES.flatMap(x=>state.cases[x.id].entries.map((e,i)=>e?{c:x,e,i}:null).filter(Boolean));openModal('我的判断',all.length?`<p style="margin-top:0">保留当时的想法，才能看见后来怎样改变了理解。</p>${all.map(({c:x,e,i})=>`<article class="notebook-entry"><h3>${x.name} · ${x.start+i*10} 年</h3><p>路线：${x.rounds[i].options[e.choice][0]}<br>配套：${supportLabels[e.support]}<br>预期：${predictLabels[e.prediction]} · 信心 ${e.confidence}%</p>${e.hypothesis?`<p><b>原始假设</b><br>${esc(e.hypothesis)}</p>`:''}${e.reflection?`<p><b>后来的修正</b><br>${esc(e.reflection)}</p>`:''}</article>`).join('')}<button class="btn" data-action="export">${ic('download')}导出全部记录</button>`:`<div class="empty">${ic('book')}<h3>还没有封存的判断</h3><p>完成一轮下注后，你的政策选择、信心与反思会保存在这里。</p><button class="btn primary" data-action="close">继续当前实验</button></div>`)}
function exportNotes(){let text='# 国运 · 历史判断记录\n\n';for(const x of CASES)for(const [i,e] of state.cases[x.id].entries.entries()){if(!e)continue;text+=`## ${x.name} ${x.start+i*10}—${x.start+(i+1)*10}\n\n优先路线：${x.rounds[i].options[e.choice][0]}\n\n配套方向：${supportLabels[e.support]}\n\n增长预测：${predictLabels[e.prediction]}；信心：${e.confidence}%\n\n原始假设：${e.hypothesis||'未填写'}\n\n修正：${e.reflection||'未填写'}\n\n`;}text+='---\n历史观察不等于政策的反事实结果。数据：世界银行 WDI。\n';let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));a.download='国运-我的判断.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('判断记录已导出')}
function updateSelection(type,value){let d=session().draft;d[type]=value;save();const attr={'choice':'choice','prediction':'prediction','support':'support'}[type];document.querySelectorAll(`[data-${attr}]`).forEach(el=>{let selected=String(value)===el.dataset[attr];el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',selected)});$('#commit').disabled=d.choice===null||d.prediction===null;$('#required-note').textContent=$('#commit').disabled?'选好政策路线和增长预期后，就可以封存判断。':'判断将被封存，随后揭示真实历史。'}
document.addEventListener('click',ev=>{let el=ev.target.closest('button');if(!el)return;if(el.dataset.country){state.country=el.dataset.country;save();closeModal();render();return}if(el.dataset.choice!==undefined){updateSelection('choice',+el.dataset.choice);return}if(el.dataset.prediction!==undefined){updateSelection('prediction',+el.dataset.prediction);return}if(el.dataset.support){updateSelection('support',el.dataset.support);return}const a=el.dataset.action;if(!a)return;const actions={countries,context,method,sources,notebook,export:exportNotes,close:closeModal,home:()=>{render()},observe:()=>{session().stage=0;save();render()},decide:()=>{session().stage=1;save();render()},commit:()=>{const d=session().draft;if(d.choice===null||d.prediction===null||session().stage!==1)return;session().entries[session().round]={...d,reflection:''};session().stage=2;save();render();toast('判断已封存。现在打开真实历史。')},explain:()=>{session().stage=3;save();render()},reveal:()=>{session().stage=2;save();render()},next:()=>{if(session().round<2){session().round++;session().stage=0;session().draft=blank().draft}else session().stage=4;save();render()}};actions[a]?.()});
document.addEventListener('input',e=>{if(e.target.id==='confidence'){session().draft.confidence=+e.target.value;$('#confidence-value').textContent=e.target.value+'%';save()}if(e.target.id==='hypothesis'){session().draft.hypothesis=e.target.value;save()}if(e.target.id==='reflection'){session().entries[session().round].reflection=e.target.value;save()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const b=$('#modal').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal()}});$('#modal').addEventListener('close',()=>document.body.classList.remove('modal-open'));render(false);
